insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b9918354-bd5b-4c29-bbab-ac41a0198ba8', 'N4', 'Vちゃう／Vじゃう (khẩu ngữ của てしまう)', 'Dạng rút gọn khẩu ngữ của てしまう', 'ちゃう/じゃう là cách nói tắt của てしまう/でしまう trong văn nói', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 39, 'Vちゃう／Vじゃう (khẩu ngữ của てしまう)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3bf46128-b422-45e6-96e2-87cdd36e3646', 'N4', '[Địa điểm]にNがVたてあります', 'Ở ~ có cái gì đang ~', 'てある dùng cho hành động ai đó đã làm và kết quả còn tồn tại', '[Địa điểm] + に + N + が + V(て form) + あります', 'Miêu tả trạng thái kết quả của 1 hành động chuẩn bị/sắp đặt trước đó tại 1 địa điểm', NULL, NULL, NULL, '{}', NULL, 39, '[Địa điểm]にNがVたてあります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5f19e512-bcdf-4259-8869-a8f22216c62e', 'N4', 'Nは[địa điểm]にVたてあります', 'Cái gì đó đang ở đâu', 'Đảo trật tự để nhấn mạnh chủ đề N thay vì địa điểm', 'N + は + [địa điểm] + に + V(て form) + あります', 'Nhấn mạnh vị trí của 1 vật cụ thể đã được ai đó sắp đặt sẵn', NULL, NULL, NULL, '{}', NULL, 39, 'Nは[địa điểm]にVたてあります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('982c3474-5685-493e-a82b-e00709033c00', 'N4', 'もうVたてあります＝もうVました', 'Đã làm gì trước, đã làm sẵn', 'もう + てある nhấn mạnh việc đã chuẩn bị/hoàn thành sẵn', 'もう + V(て form) + あります', 'Xác nhận 1 việc đã được làm/chuẩn bị xong sẵn', NULL, NULL, NULL, '{}', NULL, 39, 'もうVたてあります＝もうVました', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b896afe8-bf96-4f27-ad18-3a62706f5d13', 'N4', 'Vておく', 'Chuẩn bị trước / Làm vì mục đích gì đó', 'ておく = làm trước để chuẩn bị cho tương lai', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 39, 'Vておく', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('2f84a542-2103-4e33-88f7-5092092bc66f', 'N4', '(そのまま)Vておいてください', 'Để nguyên trạng thái như vậy', 'そのまま + ておいてください = giữ nguyên hiện trạng', '(そのまま) + V(て form) + おいてください', 'Yêu cầu ai đó giữ nguyên/không thay đổi 1 trạng thái', NULL, NULL, NULL, '{}', NULL, 39, '(そのまま)Vておいてください', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('437b4ce0-dfd7-4923-ae89-2324e31870fb', 'N4', 'Vとく＝Vておく (khẩu ngữ)', 'Cứ ~ như vậy (văn nói)', 'とく là cách nói tắt của ておく trong văn nói', 'V(て form, bỏ て) + とく', 'Dạng rút gọn khẩu ngữ của ておく trong hội thoại thân mật', NULL, NULL, NULL, '{}', NULL, 39, 'Vとく＝Vておく (khẩu ngữ)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('fb02a05c-d541-4126-84fc-8797924df5b6', 'N4', 'まだVています／まだVていません', 'Vẫn còn đang ~ / Vẫn chưa ~', 'まだ mang 2 nghĩa tùy thể khẳng định (vẫn còn) hay phủ định (vẫn chưa)', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 39, 'まだVています／まだVていません', 'pdf', 'ok')
